DROP TABLE IF EXISTS `item_upgrade_custom`;
CREATE TABLE `item_upgrade_custom` (
  `item_id` int(10) unsigned NOT NULL COMMENT 'ID de l''item actuel',
  `tier` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Palier actuel (S0, S1, M0, M+1, etc.)',
  `next_tier_item_id` int(10) unsigned DEFAULT NULL COMMENT 'ID de l''item du palier suivant',
  PRIMARY KEY (`item_id`) USING BTREE,
  KEY `idx_tier` (`tier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Items custom upgradables avec leur progression';










